(()=>{'use strict';
const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',folder:'<path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',layers:'<path d="m3 7 9-4 9 4-9 4Z M3 12l9 4 9-4 M3 17l9 4 9-4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4 M17 3v4 M3 10h18 M8 14h2 M14 14h2 M8 17h2"/>',chart:'<path d="M4 3v17h17 M8 15v-5 M13 15V7 M18 15V4"/>',sliders:'<path d="M4 7h8 M16 7h4 M4 17h4 M12 17h8"/><circle cx="14" cy="7" r="2"/><circle cx="10" cy="17" r="2"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4 M12 17h.01"/>','hard-drive':'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="M3 13h18 M6 16h1 M10 16h1"/>',moon:'<path d="M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',plus:'<path d="M12 5v14 M5 12h14"/>',arrow:'<path d="M4 12h16 M14 6l6 6-6 6"/>',play:'<path d="m8 4 12 8-12 8Z"/>',back:'<path d="m14 6-6 6 6 6"/>',download:'<path d="M12 3v12 M7 10l5 5 5-5 M4 16v4h16v-4"/>',check:'<path d="m5 12 4 4L19 6"/>',book:'<path d="M12 5v16 M12 5C8 2 4 3 2 4v15c4-2 7-1 10 2 3-3 6-4 10-2V4c-2-1-6-2-10 1Z"/>'};
function icon(n){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.grid}</svg>`}function hydrate(){$$('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon))}const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaultScript='很多企业以为，接入一个大模型就能做好 AI 客服。真正落地，需要先把问题分清楚。\n\n第一步，整理高频问题和产品资料，建立可更新的知识库。\n\n第二步，让 AI 先检索证据，再组织回答。找不到依据时，不要编造。\n\n第三步，给退款、投诉和复杂问题设置人工接管。\n\n先从一个场景开始，小范围测试，再根据真实问题持续改进。让人把时间用在更需要判断的事情上。';
const key='yingxu.mac.polished.v1';let saved={};try{const x=JSON.parse(localStorage.getItem(key)||'{}');if(x&&typeof x==='object'&&!Array.isArray(x))saved=x}catch{}
let state={view:'projects',tab:'brief',shot:1,playing:false,query:'',theme:saved.theme==='dark'?'dark':'light',script:typeof saved.script==='string'?saved.script:defaultScript,pace:['克制','自然','轻快'].includes(saved.pace)?saved.pace:'自然',volume:Number.isFinite(saved.volume)?saved.volume:22,scripts:saved.scripts&&typeof saved.scripts==='object'?saved.scripts:{},status:saved.status&&typeof saved.status==='object'?saved.status:{},custom:Array.isArray(saved.custom)?saved.custom.filter(x=>x&&typeof x.id==='string'&&typeof x.title==='string'&&typeof x.desc==='string'):[],selected:'客服'};
const baseProjects=[{id:'客服',title:'AI 客服如何落地',desc:'知识讲解 · 代码动画 · 9:16',tag:'文案已准备',color:'blue',art:'把复杂流程，讲清楚。',status:'制作中'},{id:'产品',title:'让产品自己说话',desc:'产品广告 · AI 镜头方案',tag:'待配置视频模型',color:'green',art:'留一点空间，给想象。',status:'选题与文案'},{id:'数据',title:'用数据讲一个好故事',desc:'数据解读 · 动态图表',tag:'待完善文案',color:'sand',art:'让数字，成为故事。',status:'选题与文案'}];const projects=()=>[...baseProjects,...state.custom];const current=()=>projects().find(x=>x.id===state.selected)||baseProjects[0];const projectScript=()=>state.selected==='客服'?state.script:(typeof state.scripts[state.selected]==='string'?state.scripts[state.selected]:'');const stages=['选题与文案','制作中','待导出','已归档'];
function save(){try{localStorage.setItem(key,JSON.stringify({theme:state.theme,script:state.script,scripts:state.scripts,pace:state.pace,volume:state.volume,status:state.status,custom:state.custom}));return true}catch{toast('本机保存失败，请检查浏览器存储权限');return false}}let toastTimer;function toast(t){clearTimeout(toastTimer);$('#toast').textContent=t;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4000)}
const button=(text,action,primary=false,ic='')=>`<button class="button ${primary?'primary':''}" data-action="${action}">${ic?icon(ic):''}${text}</button>`;
function nav(){const entries=[['today','grid','今日工作'],['inspiration','spark','灵感研究'],['projects','folder','内容项目'],['templates','layers','素材与方法'],['publish','calendar','发布排期'],['data','chart','数据与线索']];$('#navigation').innerHTML=entries.map(([id,i,n])=>`<button class="nav-button ${id===state.view||id==='projects'&&['project','studio','board'].includes(state.view)?'active':''}" data-view="${id}">${icon(i)}${n}${id==='projects'?`<span class="count">${projects().length}</span>`:''}</button>`).join('')}
function heading(eyebrow,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${desc}</p></div>${action}</div>`}
function art(){return `<div class="hero-art"><div class="orbits"></div><span class="art-label">YINGXU ORIGINAL / KNOWLEDGE</span><strong>让每一次提问，<br>都有更好的回答。</strong><div class="art-footer"><span>知识库</span><span>检索回答</span><span>人工接管</span></div></div>`}
function cards(list){return list.map(p=>`<article class="project-card"><div class="thumb ${p.color||'blue'}"><span class="eyebrow">${p.id==='产品'?'PRODUCT FILM':p.id==='数据'?'DATA STORY':'KNOWLEDGE'}</span><strong>${esc(p.art||p.title)}</strong></div><div class="details"><div class="row"><h3>${esc(p.title)}</h3>${icon('folder')}</div><p>${esc(p.desc)}</p><div class="row"><span class="badge ${p.id==='客服'?'green':''}">${esc(state.status[p.id]||p.tag||'新建草稿')}</span><button class="card-open" data-project="${esc(p.id)}">打开项目 ↗</button></div></div></article>`).join('')}
function projectsPage(){return heading('YOUR CREATIVE SPACE','好内容，从这里开始。','从选题到成片，把每一个想法变成作品。',button('新建项目','new',true,'plus'))+`<div class="viewbar"><div class="segmented"><button class="active" data-view="projects">项目视图</button><button data-view="board">流程看板</button></div><label class="searchbox">${icon('search')}<input id="project-search" aria-label="搜索项目" placeholder="搜索项目…" value="${esc(state.query)}"></label></div><section class="featured">${art()}<div class="feature-info"><span class="badge green">首个视频 · 示例项目</span><h2>AI 客服如何落地</h2><p>用清晰的流程动画，解释知识库、检索回答与人工接管。你的第一条知识讲解视频，从这里开始。</p><div class="feature-meta"><span>Remotion 动画</span><span>竖屏 9:16</span><span>本地制作</span></div><div class="actions">${button('继续创作','continue',true,'arrow')}${button('查看简报','brief')}</div></div></section><div class="section-heading"><h2>最近的创作</h2><p>示例项目与本机草稿</p></div><div class="project-grid" id="project-cards">${cards(projects())}</div><p class="bottom-note">设计预览 · 可编辑文案、切换分镜及调整看板。AI 生成、渲染、磁盘管理与平台发布尚未接入此页面。</p>`}
function projectPage(){const p=current();let center='';if(state.tab==='brief')center=`<div class="paper"><h3>这次，我们想讲清楚什么？</h3><p>${p.id==='客服'?'帮助中小企业负责人理解 AI 客服落地的三个步骤，说明知识库、检索回答和人工接管如何配合。':esc(p.desc)+'。此项目用于演示组织与导航，详细内容等待补充。'}</p><label>面向谁</label><div class="mini-row">企业负责人、业务运营人员</div><label>表达方式</label><div class="mini-row">清晰、克制、有具体步骤</div><label>制作方案</label><div class="mini-row">${p.id==='产品'?'AI 镜头方案':'知识讲解 · Remotion'}<span>由场景推荐</span></div><p class="bottom-note">简报只属于这个项目，不需要重复填写制作路径。</p></div>`;else if(state.tab==='script')center=`<div class="paper"><div class="section-heading" style="margin:0 0 20px"><h3>文案编辑</h3><span class="badge" id="save-status">本机草稿</span></div><textarea class="script" id="script-editor" aria-label="项目文案">${esc(projectScript())}</textarea><div class="actions" style="margin-top:18px">${button('保存文案','save-script',false,'check')}${button('AI 帮我润色','ai-script',false,'spark')}</div></div>`;else center=`<div class="paper"><h3>${state.tab==='versions'?'发布版本':'效果复盘'}</h3><p>此原型尚未生成真实视频或读取平台数据。正式接入后，这里会记录具体成片版本、发布信息和真实表现。</p><div class="actions" style="margin-top:20px">${button('查看制作界面','studio',true)}</div></div>`;return heading('PROJECT / '+esc(p.desc),esc(p.title),'从一个清晰的简报，开始一次有方向的创作。',`<div class="actions">${button('所有项目','projects',false,'back')}${button('进入制作台','studio',true,'play')}</div>`)+`<div class="project-tabs"><button data-tab="brief" class="${state.tab==='brief'?'active':''}">创作简报</button><button data-tab="script" class="${state.tab==='script'?'active':''}">文案</button><button data-action="studio">视频制作</button><button data-tab="versions" class="${state.tab==='versions'?'active':''}">发布版本</button><button data-tab="review" class="${state.tab==='review'?'active':''}">效果复盘</button></div><div class="project-body"><div>${center}</div><div><div class="paper"><h3>项目概览</h3><div class="mini-row">场景<span>${p.id==='产品'?'产品广告':'知识讲解'}</span></div><div class="mini-row">画幅<span>9:16 · 竖屏</span></div><div class="mini-row">保存方式<span>本机草稿</span></div><div class="mini-row">目标平台<span>尚未绑定</span></div></div><div class="paper"><h3>下一步</h3><p>检查文案，然后进入制作台选择镜头效果。旁白与配乐分别管理。</p><div class="actions" style="margin-top:17px">${button('编辑文案','script')}</div></div></div></div>`}
const shots=[{name:'开场 · 一个常见误区',title:'接入模型，\n不等于客服落地。',sub:'START WITH THE RIGHT QUESTION',dur:'00:00 — 00:05',flow:['提问','理解','解决']},{name:'知识库 · 先整理资料',title:'好回答，\n从好知识开始。',sub:'01 / BUILD YOUR KNOWLEDGE',dur:'00:05 — 00:15',flow:['高频问题','产品资料','知识库']},{name:'检索 · 每个回答有依据',title:'先找到证据，\n再给出答案。',sub:'02 / RETRIEVE BEFORE ANSWERING',dur:'00:15 — 00:25',flow:['用户提问','检索证据','生成回答']},{name:'接管 · 把判断留给人',title:'复杂的问题，\n交给更懂的人。',sub:'03 / KEEP HUMANS IN THE LOOP',dur:'00:25 — 00:35',flow:['复杂问题','人工接管','持续改进']}];
function studioPage(){const q=shots[state.shot];return `<div class="page-heading studio-head"><div><div class="eyebrow">PROJECT / 视频制作</div><h1>${esc(current().title)}</h1></div><div class="actions">${button('返回项目','brief',false,'back')}${button('导出草稿','export',false,'download')}${button('生成成片','render',true,'play')}</div></div><div class="studio-layout"><div class="shots"><div class="subhead"><span>分镜</span><span>04</span></div>${shots.map((x,i)=>`<button class="shot ${state.shot===i?'active':''}" data-shot="${i}"><span class="shot-thumb">${['提出问题','知识 · 整理','证据 → 回答','交给人判断'][i]}</span><span class="shot-title">${String(i+1).padStart(2,'0')} ${esc(x.name.split(' · ')[0])}</span><span class="shot-time">${i===0?'5':'10'} 秒 · 代码动画</span></button>`).join('')}</div><div class="monitor"><div class="subhead"><span>画面预览</span><span>9:16 · 画面示意</span></div><div class="canvas ${state.playing?'playing':''}"><span class="kicker">${q.sub}</span><h2>${esc(q.title).replace('\n','<br>')}</h2><div class="flow">${q.flow.map((x,i)=>(i?'<i>→</i>':'')+`<span>${x}</span>`).join('')}</div></div><div class="monitor-controls"><span>${q.dur}</span><button class="button" data-action="play">${icon('play')}${state.playing?'暂停动效':'播放动效'}</button><span>示例 35 秒 · CSS 演示</span></div></div><div class="inspector"><div class="subhead">片段属性 ${icon('sliders')}</div><div><span class="label">当前片段</span><div class="value">${q.name}</div><span class="label">制作方式</span><div class="value">Remotion 代码动画</div></div><div><label class="label" for="pace">动效节奏</label><select id="pace">${['克制','自然','轻快'].map(x=>`<option ${state.pace===x?'selected':''}>${x}</option>`).join('')}</select><span class="label">视觉模板</span><div class="value">清晰流程 · 银蓝</div></div><div><label class="label" for="volume">配乐音量 <span id="volume-value">${state.volume}%</span></label><input id="volume" type="range" min="0" max="100" value="${state.volume}"><p style="font-size:9px;line-height:1.7;margin-top:8px">参数保存到本机。当前无真实音频，不会播放配乐。</p></div><div><span class="label">输出规格</span><div class="value">1080 × 1920 · 30 fps</div></div></div><div class="timeline"><div class="subhead" style="margin-bottom:0"><span>时间线 · 示例片段规划</span><span>画面 / 旁白 / 配乐</span></div><div class="time-ruler"><span>00:00</span><span>00:05</span><span>00:15</span><span>00:25</span><span>00:35</span></div><div class="track"><span>画面</span><div class="clips">${shots.map((x,i)=>`<button class="clip ${state.shot===i?'active':''}" data-shot="${i}" style="flex:${i===0?1:2}">${x.name.split(' · ')[0]}</button>`).join('')}</div></div><div class="track"><span>旁白</span><div class="clips"><button class="clip audio-clip" data-modal="audio">旁白方案 · 等待生成或上传</button></div></div><div class="track"><span>配乐</span><div class="clips"><button class="clip music-clip" data-modal="music">轻电子氛围 · 等待选择本地音乐</button></div></div></div></div><p class="bottom-note">本页用于评审布局和操作体验；示例时长不来自真实配音。上传实拍在正式版本按实际素材时长安排。</p>`}
function boardPage(){return heading('CONTENT PIPELINE','把创作节奏，掌握在手里。','文章与视频围绕同一个选题，按各自的进度向前推进。',button('新建项目','new',true,'plus'))+`<div class="viewbar"><div class="segmented"><button data-view="projects">项目视图</button><button class="active" data-view="board">流程看板</button></div><span class="badge">本机示例状态 · 非真实生产进度</span></div><div class="board">${stages.map(stage=>{const list=projects().filter(p=>(state.status[p.id]||p.status)===stage);return `<section class="board-column"><div class="column-title">${stage}<span>${list.length}</span></div>${list.length?list.map(p=>`<article class="board-card"><span class="badge">${p.id==='产品'?'AI 镜头':'代码动画'}</span><h3>${esc(p.title)}</h3><p>${esc(p.desc)}</p><label class="muted" style="font-size:9px" for="status-${esc(p.id)}">调整示例阶段</label><select id="status-${esc(p.id)}" data-status="${esc(p.id)}">${stages.map(n=>`<option ${n===stage?'selected':''}>${n}</option>`).join('')}</select><button class="card-open" data-project="${esc(p.id)}">打开项目 ↗</button></article>`).join(''):'<p class="empty">还没有项目</p>'}</section>`}).join('')}</div>`}
function templatesPage(){return heading('ASSETS & METHODS','让好方法，成为下一次的起点。','模板定义视觉效果；素材和音乐保存在你的电脑上。',button('本地素材设置','storage'))+`<div class="section-heading"><h2>知识讲解模板</h2><span class="badge">静态样例</span></div><div class="library-grid">${[['清晰流程','01 → 02 → 03','节点依次出现，清晰解释一件事。',''],['数字叙事','从数据，到洞察。','用图表和对比表达重点。','light'],['杂志大字','让观点被看见。','用简洁排版强调一句话。','warm']].map(([n,a,d,c],i)=>`<div class="paper"><div class="template-preview ${c}">${a}</div><h3>${n}</h3><p>${d}</p><div class="actions" style="margin-top:18px"><button class="button" data-template="${i}">查看效果说明</button>${i===0?button('用于首个视频','continue',true):''}</div></div>`).join('')}</div><div class="section-heading"><h2>你的素材与声音</h2></div><div class="project-grid">${[['folder','视频与图片','引用原文件，避免重复占用空间。','storage'],['book','旁白与音色','旁白文件与音色样本分别管理。','audio'],['layers','本地音乐库','节拍、段落与响度分析待接入。','music']].map(([i,n,d,a])=>`<div class="paper">${icon(i)}<h3 style="margin-top:15px">${n}</h3><p>${d}</p><div class="actions" style="margin-top:15px">${button('查看设置',a)}</div></div>`).join('')}</div>`}
function render(){document.body.classList.toggle('dark',state.theme==='dark');nav();const title={projects:'内容项目',project:current().title,studio:'视频制作台',board:'流程看板',templates:'素材与方法',today:'今日工作',inspiration:'灵感研究',publish:'发布排期',data:'数据与线索'};$('#page-title').textContent=title[state.view]||'内容项目';let html;if(state.view==='projects')html=projectsPage();else if(state.view==='project')html=projectPage();else if(state.view==='studio')html=studioPage();else if(state.view==='board')html=boardPage();else if(state.view==='templates')html=templatesPage();else if(state.view==='today')html=heading('TODAY','把第一个想法，做成作品。','先完成一条内容，再形成自己的创作节奏。')+`<div class="featured" style="margin-top:28px">${art()}<div class="feature-info"><span class="badge">继续上次的创作</span><h2>AI 客服如何落地</h2><p>文案已经准备好。查看分镜与效果，开始你的第一条视频。</p><div class="actions" style="margin-top:25px">${button('进入制作台','continue',true)}</div></div></div>`;else html=heading(state.view==='inspiration'?'RESEARCH':state.view==='publish'?'PUBLISH':'INSIGHTS',title[state.view],state.view==='inspiration'?'发现值得讲的故事，再把它变成自己的表达。':state.view==='publish'?'让每个成片版本，都有清楚的发布去向。':'用真实的内容表现，指导下一次创作。')+`<div class="paper" style="margin-top:28px"><h3>${state.view==='inspiration'?'内嵌浏览器与视频拆解':state.view==='publish'?'这里将显示真实的发布任务':'这里将显示真实的平台数据'}</h3><p>${state.view==='inspiration'?'正式版会连接桌面内嵌浏览器，支持收藏、下载与音画拆解。此浏览器原型未连接采集服务。':'此设计原型未连接平台账号，不展示虚构的发布结果或增长指标。'}</p><div class="actions" style="margin-top:20px">${button('查看配置','settings')}${button('返回内容项目','projects')}</div></div>`;$('#content').innerHTML=html;hydrate();bind();}
function navigate(v){state.playing=false;state.view=v;render()}function openProject(id){state.selected=id;state.tab='brief';navigate('project')}
function modal(kind){let title='',body='';if(kind==='new'){title='新建内容项目';body=`<p>先给想法一个名字，其他内容可以边做边完善。</p><label for="new-title">项目名称</label><input id="new-title" maxlength="80" placeholder="你想讲一个什么故事？"><label for="new-scene">内容场景</label><select id="new-scene"><option>知识讲解 · Remotion</option><option>产品广告 · AI 镜头</option></select><div class="actions">${button('创建本机草稿','create',true)}</div>`}else if(kind==='settings'){title='管理与设置';body=`<p>配置入口设计。此原型不会读取或保存真实密钥。</p>${[['Agent 与能力','选题、文案、分镜和视频生产；按职责绑定模型。'],['模型与服务','文本 / 代码、视频、配音、转写分别接入。'],['平台账号','账号登录状态与发布能力，本地保存。'],['本地空间','素材引用、缓存上限、外置盘与项目迁移。']].map(([a,b])=>`<div class="mini-row" style="display:block"><h3>${a}</h3><p>${b}</p></div>`).join('')}<div class="actions">${button('本地存储规划','storage')}</div>`}else if(kind==='help'){title='帮助与联系';body='<p>本轮是视觉与交互原型。真实授权、生成、采集和发布由后续开发接入。</p><p style="margin-top:16px">联系刘洋：请使用已提供的首次激活页中的微信二维码。</p><a href="../index.html" target="_blank" rel="noopener">打开首次激活与微信联系页 ↗</a>'}else if(kind==='render'){title='还没有生成真实视频';body='<p>此原型没有连接 Remotion 渲染后端。当前动效是浏览器画面演示，不会产生 MP4，也不会扣费。</p><p style="margin-top:15px">下一阶段将接入现有仓库的配音、字幕、动态预览与正式渲染流程。</p>'}else if(kind==='storage'){title='本地空间';body='<h3>文件留在你的电脑上</h3><p>正式版支持选择本机或外置盘，默认引用素材，可选择复制。</p><div class="mini-row">素材重连<span>外置盘断开后重新定位</span></div><div class="mini-row">代理与缓存<span>上限设置与安全清理</span></div><div class="mini-row">任务恢复<span>空间检查与失败重试</span></div><div class="mini-row">备份迁移<span>轻量 / 完整项目包</span></div><p style="margin-top:15px">本页展示规划，不会扫描磁盘或修改文件。</p>'}else if(kind==='audio'){title='旁白与音色';body='<p>旁白可以 AI 生成、上传录音，或选择无旁白。用于克隆的音色样本在配音设置单独管理。</p><p style="margin-top:15px">此原型没有音频文件，不显示虚假的试听状态。</p>'}else if(kind==='music'){title='本地音乐库';body='<p>正式版将读取你选择的音乐目录，分析时长、响度、节拍和能量段落，再匹配视频场景。</p><p style="margin-top:15px">当前仅可在制作台调整配乐音量方案，尚未读取音乐或执行分析。</p>'}else if(kind==='ai-script'){title='文案助手';body='<p>此原型尚未连接文字模型。你可以直接编辑现有文案，所有修改保存在本机浏览器。</p>'}$('#modal-title').textContent=title;$('#modal-content').className='dialog-content';$('#modal-content').innerHTML=body;if(!$('#modal').open)$('#modal').showModal();bindModal()}
function action(a){if(['projects','board','templates'].includes(a))return navigate(a);if(a==='continue'){state.selected='客服';return navigate('studio')}if(a==='studio'){if(state.selected!=='客服'){toast('当前制作台展示“AI 客服如何落地”示范项目');state.selected='客服'}return navigate('studio')}if(a==='brief'){state.tab='brief';return navigate('project')}if(a==='script'){state.tab='script';return navigate('project')}if(a==='save-script'){if(save()){$('#save-status').textContent='已保存到本机';toast('文案已保存')}}else if(a==='play'){state.playing=!state.playing;$('.canvas').classList.toggle('playing',state.playing);$('[data-action="play"]').innerHTML=icon('play')+(state.playing?'暂停动效':'播放动效')}else if(a==='export'){const data={product:'映序 Mac 设计原型',schema:1,title:current().title,script:state.script,pace:state.pace,musicVolume:state.volume,notice:'草稿文件，不含视频或正式授权'};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='映序-创作草稿.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已发起草稿下载，不包含视频')}else if(a==='create'){const title=$('#new-title').value.trim();if(!title){$('#new-title').focus();return toast('请先填写项目名称')}const id='draft-'+crypto.randomUUID();state.custom.push({id,title,desc:$('#new-scene').value,tag:'新建草稿',status:stages[0],color:'blue',art:title});if(save()){$('#modal').close();navigate('projects');toast('本机项目草稿已创建')}}else modal(a)}
function bindModal(){$$('#modal-content [data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action))}
function bind(){$$('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$$('[data-project]').forEach(b=>b.onclick=()=>openProject(b.dataset.project));$$('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));$$('[data-modal]').forEach(b=>b.onclick=()=>modal(b.dataset.modal));$$('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render()});$$('[data-shot]').forEach(b=>b.onclick=()=>{state.shot=Number(b.dataset.shot);render()});$$('[data-status]').forEach(b=>b.onchange=()=>{state.status[b.dataset.status]=b.value;save();render()});$('#script-editor')?.addEventListener('input',e=>{if(state.selected==='客服')state.script=e.target.value;else state.scripts[state.selected]=e.target.value;if(save())$('#save-status').textContent='已自动保存'});$('#project-search')?.addEventListener('input',e=>{state.query=e.target.value;const list=projects().filter(p=>p.title.includes(state.query));$('#project-cards').innerHTML=list.length?cards(list):'<p class="empty">没有找到匹配项目</p>';$$('#project-cards [data-project]').forEach(b=>b.onclick=()=>openProject(b.dataset.project))});$('#pace')?.addEventListener('change',e=>{state.pace=e.target.value;save();toast('动效节奏方案已保存；当前画面仍为示意')});$('#volume')?.addEventListener('input',e=>{state.volume=Number(e.target.value);$('#volume-value').textContent=state.volume+'%';save()});$$('[data-template]').forEach(b=>b.onclick=()=>{const names=['清晰流程','数字叙事','杂志大字'];$('#modal-title').textContent=names[Number(b.dataset.template)]+' · 效果说明';$('#modal-content').className='dialog-content';$('#modal-content').innerHTML='<p>按内容逐步揭示重点，保持文字可读，使用克制的入场与连接动画。示例需要正式渲染后才能作为效果样片。</p>';$('#modal').showModal()})}
$('#close-modal').onclick=()=>$('#modal').close();$('#appearance').onclick=()=>{state.theme=state.theme==='light'?'dark':'light';save();render()};render();
})();
